ev("sub26a","2026-09-28",A,CA,"'삼성 AI 구독 2주년 미디어 브리핑'(삼성스토어 청담)에서 'AI 구독클럽'을 '삼성 AI 구독'으로 이름을 바꿨다. 블루패스를 고객군별로 나눠 신혼 패스(신혼부부·1인 가구: 이사 후 가전 작동 점검, 식기세척기·로봇청소기 설치·철거 시 가구 원복, 야간·공휴일 시간맞춤 세척)와 이지케어 패스(시니어: 안심케어콜 정기 전화, 전용 상담 채널)를 새로 냈다.",["nr_sub26","inews_sub26","dl_sub26","nt_sub26","asiae_sub26","deal_sub26"],tags=["구독","신혼","시니어"],imp=3,flags=["딜사이트는 시니어 패스의 이름을 적지 않음","각 패스의 구독료·가입자 수는 기사에 없음"])
ev("sub26b","2026-09-28",A,CA,"'B2B 삼성 AI 구독'을 공공기관, 호텔, 의료, 금융 고객 대상으로 내놓았다. 대량 도입 시 초기 비용 부담을 줄이고 최대 6년 무상 AS를 제공하며, 'B2B 블루패스'로 영업일 기준 48시간 이내 방문('48시간 긴급 출동'), 사업장별 담당 엔지니어, 시간맞춤 집중케어, 하나 더 서비스를 묶었다. 삼성은 B2B 구독이 시작 단계라고 설명했고 적용 제품을 금융기관 정수기·공기청정기·에어컨, 숙박시설 TV·냉장고, 사무실 PC·모니터 등으로 넓힐 예정이라고 밝혔다.",["nr_sub26","inews_sub26","dl_sub26","nt_sub26"],tags=["구독","B2B"],imp=3,flags=["적용 품목 표기가 기사마다 달라 일부만 담음","B2B 구독의 계약 건수·금액은 기사에 없음"])
ev("sub26c","2026-09-28",A,CA,"방문케어 라이트(제품 유형과 관리 방식에 따라 엔지니어 방문·특화 서비스 횟수를 줄여 구독료를 낮춘 요금)를 정수기·공기청정기·로봇청소기·에어드레서·식기세척기 구독 고객 대상으로 11월 중 도입한다고 밝혔다. 예로 에어컨(비스포크 AI 무풍콤보 갤러리 프로)은 6년 약정 기준 월 구독료가 기존 방문케어 9만 2천 원에서 8만 2천 원으로 10% 이상 낮아진다고 했다. 선납 비율 상한을 30%에서 50%로 올리고 40%·50% 선납 시 총 구독료를 5% 추가 할인한다.",["nr_sub26","inews_sub26","asiae_sub26","deal_sub26"],tags=["구독"],imp=3,flags=["뉴스룸의 11월 도입 대상 품목에 에어컨이 없는데 가격 예시는 에어컨이어서 에어컨 적용 시점은 확인 필요"])
ev("sub26d","2026-09-28",A,"실적·시장","임성택 한국총괄 부사장은 '블루패스와 함께하는 삼성 AI 구독이 출시 1년 만에 구독 1조 원을 눈앞에 두고 있다'고 말했다(스마트폰 갤럭시 AI 구독클럽은 제외). 삼성이 발표한 조사 결과로 주요 가전 구매 고객 약 3명 중 1명이 구독을 선택했고, 구독 인지도는 2024년 44%에서 2026년 7월 71%로 올랐다고 딜사이트가 전했다.",["inews_sub26","dl_sub26","deal_sub26"],tags=["구독"],claim="자사 집계",external_check=NOEXT,imp=3,flags=["'1조 원'은 눈앞이라는 발언이며 매출·계약액 여부, 누적·연간 여부, 기준일이 기사에 없음","'출시 1년'과 '2주년' 표현이 같은 기사에 함께 있음","3명 중 1명 조사의 표본·방법·유통 범위 불명","인지도 44%·71%는 딜사이트에만 있음"])
